class Solution {
public:
    int convertArray(std::vector<int>& nums) {
        auto solve = [](const std::vector<int>& arr) {
            std::priority_queue<int> pq;
            int cost = 0;
            for (int x : arr) {
                if (!pq.empty() && pq.top() > x) {
                    cost += (pq.top() - x);
                    pq.pop();
                    pq.push(x);
                }
                pq.push(x);
            }
            return cost;
        };
        std::vector<int> rev = nums;
        std::reverse(rev.begin(), rev.end());
        return std::min(solve(nums), solve(rev));
    }
};

class Solution {
    public int convertArray(int[] nums) {
        return Math.min(solve(nums), solveRev(nums));
    }

    private int solve(int[] arr) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        int cost = 0;
        for (int x : arr) {
            if (!pq.isEmpty() && pq.peek() > x) {
                cost += (pq.poll() - x);
                pq.offer(x);
            }
            pq.offer(x);
        }
        return cost;
    }

    private int solveRev(int[] arr) {
        int n = arr.length;
        int[] rev = new int[n];
        for (int i = 0; i < n; i++) rev[i] = arr[n - 1 - i];
        return solve(rev);
    }
}

class MaxHeap {
    constructor() { this.heap = []; }
    push(val) {
        this.heap.push(val);
        this._up(this.heap.length - 1);
    }
    pop() {
        const top = this.heap[0];
        const bottom = this.heap.pop();
        if (this.heap.length > 0) {
            this.heap[0] = bottom;
            this._down(0);
        }
        return top;
    }
    peek() { return this.heap[0]; }
    size() { return this.heap.length; }
    _up(i) {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this.heap[p] < this.heap[i]) {
                [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
                i = p;
            } else break;
        }
    }
    _down(i) {
        const len = this.heap.length;
        while ((i << 1) + 1 < len) {
            let best = (i << 1) + 1;
            const r = best + 1;
            if (r < len && this.heap[r] > this.heap[best]) best = r;
            if (this.heap[best] > this.heap[i]) {
                [this.heap[best], this.heap[i]] = [this.heap[i], this.heap[best]];
                i = best;
            } else break;
        }
    }
}

var convertArray = function(nums) {
    const solve = (arr) => {
        const pq = new MaxHeap();
        let cost = 0;
        for (const x of arr) {
            if (pq.size() > 0 && pq.peek() > x) {
                cost += (pq.pop() - x);
                pq.push(x);
            }
            pq.push(x);
        }
        return cost;
    };
    const rev = [...nums].reverse();
    return Math.min(solve(nums), solve(rev));
};
